    if BOX_TARGET_KEY not in state:
        state[BOX_TARGET_KEY] = None
    if LAST_ADD_KEY not in state:
        state[LAST_ADD_KEY] = None
    if ADD_COUNT_KEY not in state:
        state[ADD_COUNT_KEY] = 0

    # Get current bar's close price
    current_close = hist.close[-1]

    # Check cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Calculate entry ATR if not already set
    if state[ENTRY_ATR_KEY] is None:
        state[ENTRY_ATR_KEY] = ind.atr(hist, 14)[-1]

    # Check for MACD crossover signal
    macd_line, signal_line, _ = ind.macd(hist.close, 5, 35, 5)
    if macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]:
        # Check if past the 96-bar cooldown
        if hist.time[-1] - hist.time[state[LAST_EXIT_KEY]] >= 960 * 60 * 1000:
            # Calculate entry price and box parameters
            state[ENTRY_PRICE_KEY] = current_close
            state[BOX_ANCHOR_KEY] = current_close
            state[BOX_STOP_KEY] = current_close - state[ENTRY_ATR_KEY]
            state[BOX_TARGET_KEY] = current_close + 2 * state[ENTRY_ATR_KEY]
            state[LAST_ADD_KEY] = current_close
            state[ADD_COUNT_KEY] = 0
            state[COOLDOWN_KEY] = 4  # 4 bars cooldown
            return {"target": 0.75, "stop": state[BOX_STOP_KEY], "take": state[BOX_TARGET_KEY]}

    # Check for time stop
    if hist.time[-1] - hist.time[state[LAST_EXIT_KEY]] >= 128 * 60 * 1000:
        return {"target": 0, "stop": None, "take": None}

    # Check for box shift
    if current_close >= state[BOX_ANCHOR_KEY] + 2 * state[ENTRY_ATR_KEY]:
        state[BOX_ANCHOR_KEY] += 2 * state[ENTRY_ATR_KEY]
        state[BOX_STOP_KEY] += 2 * state[ENTRY_ATR_KEY]
        state[BOX_TARGET_KEY] += 2 * state[ENTRY_ATR_KEY]
        state[LAST_ADD_KEY] = current_close
        state[ADD_COUNT_KEY] = 0

    # Check for partial take
    if current_close >= state[BOX_ANCHOR_KEY] + 1.5 * state[ENTRY_ATR_KEY]:
        pos = pos / 2
        state[LAST_ADD_KEY] = current_close
        state[ADD_COUNT_KEY] = 0

    # Check for stop loss
    if pos > 0 and current_close <= state[BOX_STOP_KEY]:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and current_close >= state[BOX_STOP_KEY]:
        return {"target": 0, "stop": None, "take": None}

    # Check for take profit
    if pos > 0 and current_close >= state[BOX_TARGET_KEY]:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and current_close <= state[BOX_TARGET_KEY]:
        return {"target": 0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR = ind.atr(hist, 14)[-1]
    ENTRY_PRICE = hist.close[-1]
    ATR_6X = 6 * ENTRY_ATR

    # Signal
    is_long = hist.close[-1] > ind.highest(hist.close, 96)[-1]
    is_short = hist.close[-1] < ind.lowest(hist.close, 96)[-1]

    # Filter
    if 'last_trend' not in state:
        state['last_trend'] = None
    if 'last_entry' not in state:
        state['last_entry'] = None

    if is_long and state['last_trend'] != 'long':
        state['last_trend'] = 'long'
        state['last_entry'] = hist.close[-1]
    elif is_short and state['last_trend'] != 'short':
        state['last_trend'] = 'short'
        state['last_entry'] = hist.close[-1]

    if state['last_trend'] == 'long' and hist.close[-1] < state['last_entry']:
        state['last_trend'] = None
        state['last_entry'] = None
    elif state['last_trend'] == 'short' and hist.close[-1] > state['last_entry']:
        state['last_trend'] = None
        state['last_entry'] = None

    if state['last_trend'] is None:
        return {"target": 0, "stop": None, "take": None}

    # Sizing
    if 'position_size' not in state:
        state['position_size'] = 0.5

    if state['last_trend'] == 'long':
        target = min(1.0, state['position_size'] + 0.5)
    else:
        target = max(-1.0, state['position_size'] - 0.5)

    # Risk
    if 'stop_price' not in state:
        state['stop_price'] = None

    if state['last_trend'] == 'long':
        stop_price = max(ENTRY_PRICE - ENTRY_ATR, hist.low[-1])
    else:
        stop_price = min(ENTRY_PRICE + ENTRY_ATR, hist.high[-1])

    if 'take_price' not in state:
        state['take_price'] = None

    if state['last_trend'] == 'long':
        take_price = ENTRY_PRICE + ATR_6X
    else:
        take_price = ENTRY_PRICE - ATR_6X

    return {
        "target": target,
        "stop": stop_price,
        "take": take_price
    }
